<?php
namespace Alprof\Services; use PDO;
final class FinancialSummaryService {public function __construct(private PDO $db){} public function byGrade(string $month):array{$sql="SELECT gl.id,gl.name,COUNT(DISTINCT g.id) group_count,COUNT(DISTINCT s.id) student_count,COALESCE(SUM(mf.assessed_amount),0) assessed,COALESCE(SUM(mf.paid_amount),0) paid,COALESCE(SUM(mf.previous_arrears),0) arrears FROM grade_levels gl LEFT JOIN groups g ON g.grade_level_id=gl.id LEFT JOIN students s ON s.group_id=g.id AND s.status='active' LEFT JOIN monthly_fees mf ON mf.student_id=s.id AND mf.fee_month=? GROUP BY gl.id,gl.name ORDER BY gl.sort_order";$q=$this->db->prepare($sql);$q->execute([$month]);return array_map(function($r){$r['current_due']=max(0,(float)$r['assessed']-(float)$r['paid']);$r['net_debt']=$r['current_due']+(float)$r['arrears'];$r['collection_rate']=(float)$r['assessed']>0?round((float)$r['paid']/(float)$r['assessed']*100,1):0;return $r;},$q->fetchAll());}}
